from functools import wraps


def require_role(role):
    def decorator(func):
        @wraps(func)
        def wrapper(user, *args, **kwargs):
            if user.get("role") != role:
                raise PermissionError(f"{func.__name__} needs role {role}")
            return func(user, *args, **kwargs)
        return wrapper
    return decorator


@require_role("admin")
def delete_user(user, username):
    return f"{username} deleted by {user['name']}"


print(delete_user({"name": "Riya", "role": "admin"}, "kabir"))

slides.tests:
admin = {"name": "Riya", "role": "admin"}
viewer = {"name": "Kabir", "role": "viewer"}
assert delete_user(admin, "kabir") == "kabir deleted by Riya", "An admin should be allowed, and get the function's result back."
try:
    delete_user(viewer, "riya")
    raise AssertionError("A viewer calling an admin-only function should raise PermissionError.")
except PermissionError:
    pass
@require_role("editor")
def publish(user, title, draft=True):
    return (title, draft)
assert publish({"name": "Meera", "role": "editor"}, "Budget 2026", draft=False) == ("Budget 2026", False), "Pass every other argument, including keyword arguments, through to the function."
assert publish.__name__ == "publish", "Use @wraps(func) so the decorated function keeps its name."
